const cache = require('./cacheService');
const { canonicalWallet } = require('../utils/walletUtils');
const crypto = require('crypto');
const stringify = require('json-stable-stringify');

const namespaces = {
  artworkList: 'artworks:list',
  artworkDetail: 'artworks:detail',
  markerContent: 'ar_markers:content',
  profileDetail: 'profiles:detail',
  profileBatch: 'profiles:batch',
  profileArtworks: 'profiles:artworks',
  profileStats: 'profiles:stats',
  artistList: 'profiles:artists',
  statsSnapshot: 'stats:snapshot',
  statsSeries: 'stats:series',
};

function getTtl(envKey, fallbackSeconds) {
  const fallback = Number.isFinite(fallbackSeconds) && fallbackSeconds > 0
    ? fallbackSeconds
    : cache.defaultTtlSeconds();
  const parsed = parseInt(process.env[envKey], 10);
  return Number.isFinite(parsed) && parsed > 0 ? parsed : fallback;
}

function buildArtworkListKey(payload = {}) {
  return cache.buildListKey(namespaces.artworkList, payload);
}

function buildArtworkDetailKey(source, id) {
  if (!id) return null;
  const normalizedSource = source || 'postgresql';
  return cache.buildKey(namespaces.artworkDetail, `${normalizedSource}::${id}`);
}

function buildMarkerContentKey(id) {
  if (!id && id !== 0) return null;
  return cache.buildKey(namespaces.markerContent, String(id));
}

function buildProfileDetailKey(walletAddress) {
  if (!walletAddress) return null;
  const normalized = canonicalWallet(walletAddress);
  return normalized ? cache.buildKey(namespaces.profileDetail, normalized) : null;
}

function buildProfileBatchKey(wallets = []) {
  if (!Array.isArray(wallets) || wallets.length === 0) return null;
  const normalized = wallets
    .map((w) => canonicalWallet(w))
    .filter(Boolean)
    .sort();
  if (!normalized.length) return null;
  return cache.buildListKey(namespaces.profileBatch, normalized);
}

function buildProfileArtworksKey(walletAddress, payload = {}) {
  if (!walletAddress) return null;
  const normalized = canonicalWallet(walletAddress);
  if (!normalized) return null;
  return cache.buildListKey(namespaces.profileArtworks, {
    wallet: normalized,
    status: payload.status || null,
    limit: Number(payload.limit) || null,
    offset: Number(payload.offset) || null,
  });
}

function buildProfileStatsKey(walletAddress) {
  if (!walletAddress) return null;
  const normalized = canonicalWallet(walletAddress);
  return normalized ? cache.buildKey(namespaces.profileStats, normalized) : null;
}

function buildArtistListKey(payload = {}) {
  return cache.buildListKey(namespaces.artistList, {
    verified: Boolean(payload.verified),
    limit: Number(payload.limit) || null,
    offset: Number(payload.offset) || null,
  });
}

function buildStatsSnapshotKey(entityType, entityId, payload = {}) {
  if (!entityType || !entityId) return null;
  const normalizedEntityType = String(entityType).trim().toLowerCase();
  const normalizedEntityId = normalizedEntityType === 'user'
    ? canonicalWallet(entityId)
    : String(entityId).trim();
  if (!normalizedEntityId) return null;
  const hash = crypto.createHash('sha1').update(stringify(payload || {})).digest('hex');
  return cache.buildKey(namespaces.statsSnapshot, `${normalizedEntityType}::${normalizedEntityId}::${hash}`);
}

function buildStatsSeriesKey(entityType, entityId, payload = {}) {
  if (!entityType || !entityId) return null;
  const normalizedEntityType = String(entityType).trim().toLowerCase();
  const normalizedEntityId = normalizedEntityType === 'user'
    ? canonicalWallet(entityId)
    : String(entityId).trim();
  if (!normalizedEntityId) return null;
  const hash = crypto.createHash('sha1').update(stringify(payload || {})).digest('hex');
  return cache.buildKey(namespaces.statsSeries, `${normalizedEntityType}::${normalizedEntityId}::${hash}`);
}

async function invalidateStatsCache(entityType, entityId) {
  if (!cache.isEnabled()) return;
  if (!entityType || !entityId) {
    await cache.delPattern(cache.buildPattern(namespaces.statsSnapshot));
    await cache.delPattern(cache.buildPattern(namespaces.statsSeries));
    return;
  }
  const normalizedEntityType = String(entityType).trim().toLowerCase();
  const normalizedEntityId = normalizedEntityType === 'user'
    ? canonicalWallet(entityId)
    : String(entityId).trim();
  if (!normalizedEntityId) return;
  await cache.delPattern(`${namespaces.statsSnapshot}::${normalizedEntityType}::${normalizedEntityId}::*`);
  await cache.delPattern(`${namespaces.statsSeries}::${normalizedEntityType}::${normalizedEntityId}::*`);
}

async function invalidateArtworkCache(ids = []) {
  if (!cache.isEnabled()) return;
  await cache.delPattern(cache.buildPattern(namespaces.artworkList));
  const identifiers = Array.isArray(ids) ? ids : [ids];
  for (const identifier of identifiers) {
    if (!identifier && identifier !== 0) continue;
    await cache.del(buildArtworkDetailKey('postgresql', identifier));
    await cache.del(buildArtworkDetailKey('orbitdb', identifier));
  }
}

async function invalidateMarkerCache(ids = []) {
  if (!cache.isEnabled()) return;
  const identifiers = Array.isArray(ids) ? ids : [ids];
  for (const identifier of identifiers) {
    if (!identifier && identifier !== 0) continue;
    const key = buildMarkerContentKey(identifier);
    if (key) {
      await cache.del(key);
    }
  }
}

async function invalidateProfileCache(wallets = []) {
  if (!cache.isEnabled()) return;
  const identifiers = Array.isArray(wallets) ? wallets : [wallets];
  for (const wallet of identifiers) {
    if (!wallet) continue;
    await cache.del(buildProfileDetailKey(wallet));
    await cache.del(buildProfileStatsKey(wallet));
  }
  await cache.delPattern(cache.buildPattern(namespaces.profileArtworks));
  await cache.delPattern(cache.buildPattern(namespaces.profileBatch));
}

async function invalidateArtistListCache() {
  if (!cache.isEnabled()) return;
  await cache.delPattern(cache.buildPattern(namespaces.artistList));
}

module.exports = {
  cache,
  namespaces,
  getTtl,
  buildArtworkListKey,
  buildArtworkDetailKey,
  buildMarkerContentKey,
  buildProfileDetailKey,
  buildProfileBatchKey,
  buildProfileArtworksKey,
  buildProfileStatsKey,
  buildArtistListKey,
  buildStatsSnapshotKey,
  buildStatsSeriesKey,
  invalidateArtworkCache,
  invalidateMarkerCache,
  invalidateProfileCache,
  invalidateArtistListCache,
  invalidateStatsCache,
};
